/** Caller-access modes documented by the phone-service HCL resource. */
export const callerAccessMode = {
    allowAll: "ALLOW_ALL",
    knownCallersOnly: "KNOWN_CALLERS_ONLY",
};
/** Runtime backstop for JavaScript callers and dynamically constructed input. */
export function validatePhoneService(name, service) {
    const fail = (message) => {
        throw new Error(`phoneService "${name}": ${message}`);
    };
    const existing = service.twilioExistingNumber;
    const created = service.twilioNewNumber;
    if ((existing === undefined) === (created === undefined)) {
        fail("set exactly one of twilioExistingNumber or twilioNewNumber");
    }
    if (existing !== undefined && !/^\+[1-9]\d{7,14}$/.test(existing.phoneNumber)) {
        fail("twilioExistingNumber.phoneNumber must be an E.164 number such as +14155551234");
    }
    if (created !== undefined && !Number.isInteger(created.areaCode)) {
        fail("twilioNewNumber.areaCode must be an integer");
    }
}
